"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["78722"],{83147(e){e.exports=JSON.parse('{"id":"FIN-1127","slug":"backlog","term":"Backlog","also_known_as":[],"difficulty":"Advanced","definition":"Backlog is the value of orders or contracts a company has received but not yet fulfilled, representing revenue it expects to recognise in future.","explanation":["Backlog, also called order book or remaining performance obligations in some reporting, shows how much work a company already has lined up. It is especially important in industries with long production or delivery times, such as aircraft manufacturing, shipbuilding, defence, construction and heavy engineering.","For example, an aircraft maker with orders for 500 aircraft not yet delivered might report a backlog worth many years of production. A construction company might report a backlog of 120,000,000 in signed contracts not yet completed.","A growing backlog generally signals strong demand and gives visibility over future revenue. A shrinking backlog can warn of slowing business.","Backlog has limitations. Orders can be cancelled or delayed, customers can run into financial difficulty and costs may rise, making some contracts less profitable than expected. Companies also define backlog differently. Under current revenue standards, companies disclose remaining performance obligations, which provides a more consistent measure of contracted future revenue."],"note":"","total":1500,"prev":{"slug":"average-selling-price","term":"Average Selling Price (ASP)"},"next":{"slug":"backtesting","term":"Backtesting"}}')}}]);